/** A demo file's text, by its repo path (the harness reads F-1's file set, R-3). */
export const readRaw = (file: string): string => read(file);

/**
 * The SFC a manifest row routes to: the one `<id>.vue` under its category's directory,
 * at the root or in a group directory, which is the manifest's own rule
 * (`demo/stories/manifest/lazy.ts`). None or several is an error.
 */
export const storyFile = (cat: string, id: string): string => {
    const hits = files({ under: `demo/stories/${cat}`, suffix: `/${id}.vue` });
    if (hits.length !== 1) throw new Error(`story ${cat}/${id}: ${hits.length} files named ${id}.vue (${hits.join(", ")})`);
    return hits[0];
};

